/**
 * File Description: Input/output corpus for the unified model-reply parser. The reply samples are AUTHORED, not
 * captured (no raw fenced model reply survives on disk; the real Gemini reply is covered in
 * backend/geminiReview/geminiReview.expect.test.ts). They exercise plain JSON, fenced JSON with surrounding prose, and
 * nested JSON; parser output is generated by the real code and stored as reviewed expectations.
 * Inputs and outputs: authored raw model reply samples -> clean JSON text and parsed value expectations.
 * Used by: npm test (found by glob), the CI unit job.
 */

import test from "node:test";
import { expectFile, formatForReview } from "./testSupport/expectFile";
import { cleanModelJsonResponse, parseModelJson } from "./modelReply";

// AUTHORED samples (not captured), one per reply shape the parser must handle.
const replies = [
  {
    id: "plain-json",
    raw: '{"status":"ok","count":3}',
  },
  {
    id: "fenced-review-json",
    raw: 'Review result:\n```json\n{"verdict":"ACCEPT","criteria":[{"name":"readability","score":9.2}]}\n```\nDone.',
  },
  {
    id: "nested-json",
    raw: '```python\n{"payload":{"items":[{"name":"alpha","enabled":true},{"name":"beta","enabled":false}]}}\n```',
  },
];

// Records each parser result in stable JSON for diff review.
test("model reply parser matches the authored reply corpus", () => {
  const outputs = replies.map(({ id, raw }) => ({
    id,
    cleaned: cleanModelJsonResponse(raw),
    parsed: parseModelJson(raw),
  }));
  expectFile(formatForReview(outputs), "model-reply/parser.json");
});
